    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row),
             key=lambda v: sum(row.count(v) for row in g))

    # Long colored border runs are the rails; interior marks project
    # parallel to the rail, toward the nearest rail.
    rails = []
    for r in range(h):
        for c in range(w):
            v = g[r][c]
            if v == bg:
                continue
            if r in (0, h - 1) or c in (0, w - 1):
                rails.append((r, c, v))

    marks = [(r, c, g[r][c]) for r in range(h) for c in range(w)
             if g[r][c] != bg and (r, c) not in [(a, b) for a, b, _ in rails]]
    for r, c, color in marks:
        if not rails:
            continue
        rr, cc, _ = min(rails, key=lambda p: abs(p[0]-r) + abs(p[1]-c))
        g[r][c] = 4
        if rr in (0, h - 1):
            # Vertical projection, keeping the mark's column.
            step = 1 if rr == 0 else -1
            y = r + step
            while 0 <= y < h and g[y][c] == bg:
                g[y][c] = color
                y += step
        else:
            step = 1 if cc == 0 else -1
            x = c + step
            while 0 <= x < w and g[r][x] == bg:
                g[r][x] = color
                x += step
    return g
