def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Interior marks project in a straight line toward the nearest edge.
    marks = [(r, c, g[r][c]) for r in range(h) for c in range(w)
             if g[r][c] != bg and c not in (0, w - 1)
             and r not in (0, h - 1)]

    for r, c, color in marks:
        g[r][c] = 4
        if c <= w - 1 - c:
            step = -1
        else:
            step = 1
        x = c + step
        while 0 <= x < w and g[r][x] == bg:
            g[r][x] = color
            x += step

    return g
